package com.faust.epiccompat;
import com.faust.core.runtime.CoreRuntime;
import net.minecraft.world.item.*;
import yesman.epicfight.world.capabilities.EpicFightCapabilities;
import yesman.epicfight.world.capabilities.entitypatch.player.ServerPlayerPatch;
import yesman.epicfight.skill.*;
@net.neoforged.fml.common.EventBusSubscriber(modid="faust_epic_compat")
public final class CombatRefinementRuntime {
 private static void check(boolean ok,String why){if(!ok)throw new AssertionError(why);}
 @net.neoforged.bus.api.SubscribeEvent(priority=net.neoforged.bus.api.EventPriority.HIGH)
 public static void started(net.neoforged.neoforge.event.server.ServerStartedEvent e){
  var player=net.neoforged.neoforge.common.util.FakePlayerFactory.get(e.getServer().overworld(),new com.mojang.authlib.GameProfile(java.util.UUID.randomUUID(),"RefinementChecks"));player.gameMode.changeGameModeForPlayer(net.minecraft.world.level.GameType.SURVIVAL);player.setOnGround(true);var patch=EpicFightCapabilities.getEntityPatch(player,ServerPlayerPatch.class);var p=CoreRuntime.data(player);var b=CoreRuntime.balance;p.max(b);patch.toEpicFightMode(false);player.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,new ItemStack(Items.IRON_SWORD));var container=patch.getSkill(SkillSlots.GUARD);
  for(String name:java.util.List.of("guard","parrying","impact_guard")){
   var skill=yesman.epicfight.registry.EpicFightRegistries.SKILL.get(net.minecraft.resources.ResourceLocation.parse("epicfight:"+name));container.setSkill(skill);
   for(int i=0;i<3;i++){p.stamina=10;p.exhausted=false;check(container.requestHold(patch,new net.minecraft.nbt.CompoundTag()),"valid press starts "+name);check(Math.abs(p.stamina-9)<0.001,"each guard press costs exactly1 "+name);patch.resetHolding();}
   p.stamina=10;p.exhausted=false;check(patch.startSkillHolding((yesman.epicfight.skill.modules.HoldableSkill)skill)&&Math.abs(p.stamina-9)<0.001,"direct holding entry charges exactly1 "+name);patch.resetHolding();p.stamina=10;p.exhausted=false;((yesman.epicfight.skill.guard.GuardSkill)skill).startHolding(container);check(Math.abs(p.stamina-9)<0.001&&container.isActivated(),"direct guard entry charges1 "+name);((yesman.epicfight.skill.guard.GuardSkill)skill).resetHolding(container);
   p.stamina=0.5;p.exhausted=false;check(!container.requestHold(patch,new net.minecraft.nbt.CompoundTag())&&p.stamina==0.5,"fractional stamina cannot begin guard "+name);
  }
  p.stamina=5;p.exhausted=false;var animation=patch.getAnimator().getPlayerFor(null);animation.setPlayAnimation(yesman.epicfight.gameasset.Animations.GREATSWORD_AUTO1);animation.setElapsedTime(0.1F);Forbidden.TICK.set(player);try{p.secondWind(1,b);check(p.stamina==5,"no Second Wind during attack animation");animation.setPlayAnimation(yesman.epicfight.gameasset.Animations.BIPED_IDLE);p.secondWind(1,b);check(p.stamina==5,"Second Wind remains paused after animation");long now=player.serverLevel().getGameTime();((net.minecraft.world.level.storage.ServerLevelData)player.serverLevel().getLevelData()).setGameTime(now+19);p.secondWind(1,b);check(p.stamina==5,"19 ticks still paused");((net.minecraft.world.level.storage.ServerLevelData)player.serverLevel().getLevelData()).setGameTime(now+20);p.secondWind(1,b);check(p.stamina>5,"Second Wind returns after20 ticks");}finally{Forbidden.TICK.remove();}
  player.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,new ItemStack(yesman.epicfight.registry.entries.EpicFightItems.IRON_LONGSWORD.get()));var longSource=new yesman.epicfight.world.damagesource.EpicFightDamageSource(player.damageSources().playerAttack(player)).setUsedItem(player.getMainHandItem()).setBaseArmorNegation(20);check(longSource.calculateArmorNegation()==40,"longsword armor negation2x");p.disabled.add(WeaponMastery.LONG);check(longSource.calculateArmorNegation()==20,"disabled longsword has no bonus");p.disabled.remove(WeaponMastery.LONG);
  player.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,new ItemStack(yesman.epicfight.registry.entries.EpicFightItems.IRON_GREATSWORD.get()));var speed=player.getAttribute(net.minecraft.world.entity.ai.attributes.Attributes.MOVEMENT_SPEED);var penalty=net.minecraft.resources.ResourceLocation.withDefaultNamespace("greatsword_movement_speed_penalty");speed.addTransientModifier(new net.minecraft.world.entity.ai.attributes.AttributeModifier(penalty,-0.02,net.minecraft.world.entity.ai.attributes.AttributeModifier.Operation.ADD_VALUE));double penalized=speed.getValue();WeaponMastery.refreshSpeed(player);check(Math.abs(speed.getValue()-penalized-0.02)<0.001,"greatsword item movement penalty cancelled");WeaponMastery.refreshSpeed(player);check(Math.abs(speed.getValue()-penalized-0.02)<0.001,"speed compensation does not accumulate");p.disabled.add(WeaponMastery.GREAT);WeaponMastery.refreshSpeed(player);check(Math.abs(speed.getValue()-penalized)<0.001,"disabling mastery restores weapon penalty");
  var great=b.abilities.stream().filter(a->a.id().equals(WeaponMastery.GREAT)).findFirst().orElseThrow();check(great.amount()==250&&great.parent().equals(Combat.MASTERY),"250 swings and two handed grip dependency");
  p.disabled.remove(WeaponMastery.GREAT);player.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,new ItemStack(Items.IRON_SWORD));
  var escape=yesman.epicfight.registry.EpicFightRegistries.SKILL.get(net.minecraft.resources.ResourceLocation.parse("epicfight:emergency_escape"));
  var passive=patch.getSkill(SkillSlots.PASSIVE1);check(passive.setSkill(escape),"equip emergency escape");passive.setStack(1);
  var dodge=patch.getSkill(SkillSlots.DODGE);dodge.setSkill(yesman.epicfight.registry.EpicFightRegistries.SKILL.get(net.minecraft.resources.ResourceLocation.parse("epicfight:roll")));
  patch.getAnimator().getPlayerFor(null).setPlayAnimation(yesman.epicfight.gameasset.Animations.BIPED_IDLE);player.setOnGround(true);p.stamina=0;p.exhausted=true;
  check(EmergencyDodge.available(patch),"charged escape available while exhausted");
  check(dodge.requestCasting(patch,new net.minecraft.nbt.CompoundTag()),"actual exhausted dodge executes");
  check(passive.getStack()==0,"emergency dodge spends cooldown");check(!EmergencyDodge.available(patch),"second emergency dodge unavailable");
  check(!dodge.requestCasting(patch,new net.minecraft.nbt.CompoundTag()),"second exhausted dodge rejected");
  passive.setStack(1);p.stamina=5;p.exhausted=true;patch.getAnimator().getPlayerFor(null).setPlayAnimation(yesman.epicfight.gameasset.Animations.BIPED_IDLE);player.setOnGround(true);patch.updateEntityState();check(dodge.requestCasting(patch,new net.minecraft.nbt.CompoundTag()),"escape works during partial exhaustion recovery");check(passive.getStack()==0&&p.stamina==5,"partial recovery escape spends cooldown only");
  var skills=b.abilities;for(var req:java.util.Map.of("adaptive_skin",12,"death_harvest",7,"catharsis",1).entrySet()){var a=skills.stream().filter(x->x.id().endsWith("/"+req.getKey())).findFirst().orElseThrow();check(a.skill()==com.faust.essence.api.Skill.valueOf("constitution")&&a.level()==req.getValue(),"constitution requirement "+req.getKey());if(req.getKey().equals("catharsis"))check(a.skillRequirements().size()==6&&a.skillRequirements().stream().allMatch(x->x.level()==1),"catharsis all six characteristics1");}
  check(skills.stream().filter(a->a.id().equals("faustcore:training_constitution_health")).findFirst().orElseThrow().level()==10,"health requires constitution10");
  var nodes=b.trees.stream().filter(t->t.skill()==com.faust.essence.api.Skill.valueOf("strength")).findFirst().orElseThrow().nodes();var emergency=nodes.stream().filter(n->n.ability().endsWith("/emergency_escape")).findFirst().orElseThrow();var bone=nodes.stream().filter(n->n.ability().endsWith("/bonebreaker")).findFirst().orElseThrow();var greatNode=nodes.stream().filter(n->n.ability().equals(WeaponMastery.GREAT)).findFirst().orElseThrow();check(emergency.y()==bone.y()&&emergency.x()==greatNode.x(),"actual adrenaline escape red dot position");
  System.out.println("Combat refinement and exhausted emergency dodge gameplay checks passed");
 }
}
